# ── CHAK DHIS2 config (for MOH 740 / MOH 731) ──────────────────────
CHAK_BASE = "https://ereporting.chak.or.ke/api"
CHAK_USER = "Johnbrian"
CHAK_PASS = "JOHNb123\\"

# ── CHAK transport resolution ───────────────────────────────────────
# CHAK retired the old plain-HTTP port 8500.  The same DHIS2 instance is now
# reached over TLS at https://ereporting.chak.or.ke/api — same server, same
# credentials — so that TLS URL is the single canonical base.
#
# CHAK_BASE is the built-in default, DHIS_BASE_URL may pin a different server
# (it wins over the default), and the last base that actually answered is
# remembered per process.  In a normal deployment every candidate is the same
# TLS URL.
#
# A base that raises a *connection* error is quarantined for a cooldown, so an
# unreachable host costs ONE ~4 s connect attempt per window instead of ~4 s on
# every single call.
_CHAK_LOCK = threading.Lock()
_CHAK_GOOD_BASE = None              # resolved winner, remembered per process
_CHAK_FAILED_AT = {}                # base -> time.monotonic() of last failure
_CHAK_COOLDOWN = float(os.getenv("CHAK_BASE_COOLDOWN", "120"))

# (connect, read).  Split so an unreachable host costs ~4 s instead of the full
# read budget; a *reachable* CHAK still needs a generous read timeout because
# its analytics queries legitimately take 10-35 s.
_CHAK_CONNECT_TIMEOUT = float(os.getenv("CHAK_CONNECT_TIMEOUT", "4"))
_CHAK_DEFAULT_READ_TIMEOUT = float(os.getenv("CHAK_READ_TIMEOUT", "240"))

# Read budgets for the two heavy analytics shapes.  Both are env-tunable so an
# operator can shorten them on a platform whose worker timeout is smaller than
# CHAK's worst-case latency.
_CHAK_ANALYTICS_READ_TIMEOUT = float(
    os.getenv("CHAK_ANALYTICS_READ_TIMEOUT", "120"))
_CHAK_COC_READ_TIMEOUT = float(
    os.getenv("CHAK_COC_READ_TIMEOUT", "240"))

# A base already inside its cooldown window is only being *probed* to notice
# CHAK recovering, so it must not re-pay a full 120/240 s budget.  A read
# timeout is a RequestException, so it is recorded as a failure too — before
# this cap, ONE blackholed call made every later call in the same build hang
# for the whole budget (measured: a single cold milestone build took 380 s).
_CHAK_PROBE_READ_TIMEOUT = float(
    os.getenv("CHAK_PROBE_READ_TIMEOUT", "6"))


def chak_bases():
    """Ordered CHAK base URLs: last known good, then the default, then env."""
    env_base = (os.getenv("DHIS_BASE_URL") or "").strip().rstrip("/")
    with _CHAK_LOCK:
        good = _CHAK_GOOD_BASE
    out = []
    for base in (good, CHAK_BASE, env_base):
        if base and base not in out:
            out.append(base)
    return out


def chak_get(path, params, read_timeout=None, auth=None):
    """GET a CHAK DHIS2 path, walking the candidate bases until one answers.

    `path` starts with '/'.  Returns the first response obtained from a
    *reachable* server — an HTTP 4xx/5xx is returned to the caller rather than
    triggering another base, because a server that rejects the query on one
    transport would reject it on the other too.

    Raises the last transport exception when no base is reachable, so each
    caller's existing `except` handling keeps working unchanged.
    """
    import requests as _req
    from requests.auth import HTTPBasicAuth

    global _CHAK_GOOD_BASE

    if auth is None:
        auth = HTTPBasicAuth(CHAK_USER, CHAK_PASS)
    # Caller-pinned read budget, else the generous default.  The heavy
    # analytics callers pass their own via _CHAK_ANALYTICS_READ_TIMEOUT /
    # _CHAK_COC_READ_TIMEOUT.
    want_read = read_timeout or _CHAK_DEFAULT_READ_TIMEOUT

    last_exc = None
    tried = []
    now = time.monotonic()
    candidates = chak_bases()

    def _in_cooldown(base):
        with _CHAK_LOCK:
            failed_at = _CHAK_FAILED_AT.get(base)
        return failed_at is not None and (now - failed_at) < _CHAK_COOLDOWN

    live = [b for b in candidates if not _in_cooldown(b)]
    if not live:
        # Everything is inside its cooldown window.  Now that there is
        # effectively ONE endpoint, refusing to try would black-hole every
        # request for the whole window, so probe anyway — a half-open retry
        # that recovers the moment CHAK is back.
        print("[DHIS2] all CHAK bases in cooldown; probing anyway "
              f"(read budget capped at {_CHAK_PROBE_READ_TIMEOUT:g}s for "
              f"{', '.join(candidates) or 'none'})")
        live = list(candidates)

    for base in live:
        url = base.rstrip("/") + path
        # Cap the read budget for a base we are only probing.  Without this
        # a base that just blackholed would be re-probed at the full
        # 120/240 s budget on every subsequent call in the same build.
        if _in_cooldown(base):
            timeout = (_CHAK_CONNECT_TIMEOUT,
                       min(want_read, _CHAK_PROBE_READ_TIMEOUT))
        else:
            timeout = (_CHAK_CONNECT_TIMEOUT, want_read)
        try:
            resp = _req.get(url, params=params, auth=auth, verify=False,
                            timeout=timeout)
        except _req.exceptions.RequestException as exc:
            with _CHAK_LOCK:
                _CHAK_FAILED_AT[base] = time.monotonic()
            last_exc = exc
            tried.append(f"{base} ({type(exc).__name__})")
            print(f"[DHIS2] CHAK base unreachable: {base} - "
                  f"{type(exc).__name__}: {exc}")
            continue
        with _CHAK_LOCK:
            _CHAK_GOOD_BASE = base
            _CHAK_FAILED_AT.pop(base, None)
        return resp

    print(f"[DHIS2] no reachable CHAK base (tried: {'; '.join(tried) or 'none'})")
    if last_exc is not None:
        raise last_exc
    raise ConnectionError("all CHAK base URLs are in cooldown")


def _normalize_pe(pe):
    """Coerce a period expression into the form DHIS2's `pe` dimension wants.

    DHIS2 periods are compact ("202606", "2026Q2", "2026") or relative
    ("LAST_12_MONTHS").  The single-month picker in the UI is an HTML
    ``<input type="month">``, which emits "2026-06" — DHIS2 silently returns
    **no rows** for that, so every single-month view rendered empty.  Collapse
    the YYYY-MM form (including each part of a semicolon-joined list) to YYYYMM.
    """
    if not pe:
        return pe
    txt = str(pe).strip()
    if ";" in txt:
        return ";".join(
            _normalize_pe(part) for part in txt.split(";") if part.strip()
        )
    if re.fullmatch(r"\d{4}-\d{2}", txt):
        return txt.replace("-", "")
    return txt


def _parse_dhis2_rows(rows, meta, coc_ids=None):
    """Parse DHIS2 analytics rows into a dict."""
    if not rows:
        return {}
    out = {}
    if coc_ids:
        # COC-disaggregated: keyed by (period, coc_id)
        # Row format: [dx, coc, pe, ou, value] when ou dimension is present
        for row in rows:
            if len(row) < 4:
                continue
            coc = str(row[1]) if len(row) > 1 else ""
            pe_code = str(row[2]) if len(row) > 2 else ""
            pe_name = meta.get(pe_code, {}).get("name", pe_code)
            val = float(row[-1]) if row[-1] else 0
            out[(pe_name, coc)] = out.get((pe_name, coc), 0) + val
    else:
        # Simple period-summed
        for row in rows:
            pe_code = str(row[1]) if len(row) > 1 else ""
            pe_name = meta.get(pe_code, {}).get("name", pe_code)
            val = float(row[-1]) if row[-1] else 0
            out[pe_name] = out.get(pe_name, 0) + val
    return out


def _dhis2_fetch(dx_ids, ou_id, pe="LAST_12_MONTHS", coc_ids=None):
    """Fetch analytics rows from DHIS2.
    Returns:
      - Without coc_ids: dict of {period_label: summed_value}
      - With coc_ids: dict of {(period_label, coc_id): value}
    dx_ids can be a single string or a list/set of strings.
    """
    from services.analytics_cache import get as cache_get, make_key, store as cache_set

    if isinstance(dx_ids, (list, set, tuple)):
        dx_str = ";".join(dx_ids)
    else:
        dx_str = dx_ids

    if not dx_str or not dx_str.strip():
        return {}  # no DX IDs to query

    pe = _normalize_pe(pe)

    # Build dimensions – ou_id can be a single ID or list
    if isinstance(ou_id, (list, set, tuple)):
        ou_str = ";".join(ou_id)
    else:
        ou_str = ou_id

    cache_key = make_key(dx_str, ou_str, pe, coc_ids, namespace="chak")
    hit = cache_get(cache_key)
    if hit is not None:
        return hit

    from requests.auth import HTTPBasicAuth

    username = os.getenv("DHIS_USERNAME", CHAK_USER)
    password = os.getenv("DHIS_PASSWORD", CHAK_PASS)
    auth = HTTPBasicAuth(username, password)

    dimensions = [f"dx:{dx_str}", f"pe:{pe}", f"ou:{ou_str}"]
    if coc_ids:
        if isinstance(coc_ids, (list, set, tuple)):
            coc_str = ";".join(coc_ids)
        else:
            coc_str = coc_ids
        dimensions.append(f"co:{coc_str}")

    params = {
        "dimension": dimensions,
        "displayProperty": "NAME",
    }
    # NOTE: this call used to try ai_translator's `fetch_query_result` first.
    # That was dead code — it returns rows shaped [{period, metric, facility,
    # value}] while `_parse_dhis2_rows` reads positional arrays, so the branch
    # always raised KeyError, was swallowed by `except Exception: pass`, and
    # fell straight through to here.  Its only effect was a SECOND full
    # analytics query per metric against an already slow CHAK server, so the
    # round-trip was removed rather than repaired.  (Superpower's parsed output
    # also drops the `co` dimension, so it could never have served the
    # COC-disaggregated callers anyway.)
    resp = chak_get("/analytics.json", params,
                    read_timeout=_CHAK_ANALYTICS_READ_TIMEOUT, auth=auth)
    if not resp.ok:
        return {}
    data = resp.json()
    rows = data.get("rows", [])
    meta = data.get("metaData", {}).get("items", {})
    parsed = _parse_dhis2_rows(rows, meta, coc_ids)
    cache_set(cache_key, parsed)
    return parsed


def _chak_analytics_fetch(dx_ids, ou_id, pe="LAST_12_MONTHS"):
    """Fetch analytics rows from CHAK DHIS2.
    Returns {dx_id: {period_name: value, ...}, ...}
    """
    from services.analytics_cache import get as cache_get, make_key, store as cache_set

    from requests.auth import HTTPBasicAuth

    from services.khis import _khis_parse_per_de

    auth = HTTPBasicAuth(CHAK_USER, CHAK_PASS)
    if isinstance(dx_ids, (list, set, tuple)):
        dx_str = ";".join(dx_ids)
    else:
        dx_str = dx_ids
    if not dx_str or not dx_str.strip():
        return {}
    if isinstance(ou_id, (list, set, tuple)):
        ou_str = ";".join(ou_id)
    else:
        ou_str = ou_id

    pe = _normalize_pe(pe)
    cache_key = make_key(dx_str, ou_str, pe, namespace="chak")
    hit = cache_get(cache_key)
    if hit is not None:
        return hit

    params = {
        "dimension": [f"dx:{dx_str}", f"pe:{pe}", f"ou:{ou_str}"],
        "displayProperty": "NAME",
    }
    try:
        resp = chak_get("/analytics.json", params,
                        read_timeout=_CHAK_ANALYTICS_READ_TIMEOUT, auth=auth)
        if not resp.ok:
            return {}
        data = resp.json()
        rows = data.get("rows", [])
        meta = data.get("metaData", {}).get("items", {})
        result = _khis_parse_per_de(rows, meta)
        cache_set(cache_key, result)
        return result
    except Exception:
        return {}


def _chak_analytics_fetch_coc(dx_id, ou_ids, pe="LAST_12_MONTHS",
                              name_prefixes=None, ou_chunk=100):
    """Fetch one CHAK data element by category option and keep only the
    options whose NAME starts with one of `name_prefixes`.

    CHAK DHIS2 2.40 ignores `co:<option-uid>` as a dimension filter — it
    returns the element's grand total regardless — so the element must be
    pulled with `co:categoryOptions` and filtered client-side on the
    category-option display name.

    Used for #9 IIT: 'C&T (facility) - Tx_ML, Outcomes' splits into Died /
    Transferred Out / Refused (Stopped) / Interruption (<3m, 3-5m, 6+m);
    only the 'Interruption' options are IIT.

    Returns {period_name: summed_value} — {} on any failure.
    """
    from services.analytics_cache import get as cache_get, make_key, store as cache_set

    from requests.auth import HTTPBasicAuth

    if isinstance(ou_ids, (list, set, tuple)):
        ou_list = list(ou_ids)
    else:
        ou_list = [ou_ids]
    ou_list = [str(o) for o in ou_list if o]
    if not ou_list:
        return {}

    prefixes = tuple(name_prefixes or ())
    pe = _normalize_pe(pe)
    cache_key = make_key(dx_id, ";".join(ou_list), pe, prefixes,
                         namespace="chak_coc")
    hit = cache_get(cache_key)
    if hit is not None:
        return hit

    auth = HTTPBasicAuth(CHAK_USER, CHAK_PASS)
    chunks = [ou_list[i:i + ou_chunk]
              for i in range(0, len(ou_list), ou_chunk)]

    def _one_chunk(chunk):
        """Fetch and parse a single OU chunk -> {period_name: summed_value}.

        Raises on transport/HTTP failure so the caller can abort the whole
        read: a silently dropped chunk would UNDER-count IIT, which is far
        worse than returning no data at all.
        """
        params = {
            "dimension": [f"dx:{dx_id}", "co:categoryOptions", f"pe:{pe}",
                          "ou:" + ";".join(chunk)],
            "paging": "false",
        }
        resp = chak_get("/analytics.json", params,
                        read_timeout=_CHAK_COC_READ_TIMEOUT, auth=auth)
        if not resp.ok:
            raise RuntimeError(f"CHAK COC fetch HTTP {resp.status_code}")
        data = resp.json()
        rows = data.get("rows", []) or []
        if not rows:
            return {}
        meta = data.get("metaData", {}).get("items", {})
        hdrs = [h.get("name") for h in (data.get("headers") or [])]
        try:
            co_i, pe_i = hdrs.index("co"), hdrs.index("pe")
            val_i = hdrs.index("value")
        except ValueError:
            co_i, pe_i, val_i = 1, 2, len(rows[0]) - 1
        part = {}
        for row in rows:
            if len(row) <= max(co_i, pe_i, val_i):
                continue
            name = (meta.get(str(row[co_i]), {}) or {}).get("name", "") or ""
            if prefixes and not name.startswith(prefixes):
                continue
            pe_name = (meta.get(str(row[pe_i]), {}) or {}).get(
                "name", str(row[pe_i]))
            try:
                val = float(row[val_i] or 0)
            except (TypeError, ValueError):
                continue
            part[pe_name] = part.get(pe_name, 0) + val
        return part

    # CHAK takes ~7-10 s per analytics request whatever its size, so the
    # chunks are fetched concurrently rather than back to back.  Results are
    # merged in the original chunk order, so the sum is identical to the
    # sequential path.
    from concurrent.futures import ThreadPoolExecutor

    out = {}
    with ThreadPoolExecutor(max_workers=min(4, len(chunks))) as ex:
        try:
            for part in ex.map(_one_chunk, chunks):
                for pe_name, val in part.items():
                    out[pe_name] = out.get(pe_name, 0) + val
        except Exception as exc:  # noqa: BLE001
            print(f"[DHIS2] CHAK COC fetch failed: {exc}")
            return {}
    cache_set(cache_key, out)
    return out


def _chak_analytics_coc_cells(dx_ids, ou_ids, pe="LAST_12_MONTHS",
                              ou_chunk=100):
    """Fetch data element(s) disaggregated by category option combo.

    Both Daraja funding namespaces share the SAME 30 age × sex COCs
    (`_COC_MALES` / `_COC_FEMALES`), so one request over
    `dx:kgzd9LfXZXq;aMp82zBYPnx` with `co:categoryOptions` yields the correct
    gender/age split for the whole 259-facility roster.

    Returns {period_name: {coc_uid: value}} — {} on any failure.
    """
    from services.analytics_cache import get as cache_get, make_key, store as cache_set

    from requests.auth import HTTPBasicAuth

    if isinstance(ou_ids, (list, set, tuple)):
        ou_list = [str(o) for o in ou_ids if o]
    else:
        ou_list = [str(ou_ids)] if ou_ids else []
    if not ou_list:
        return {}

    dx_key = dx_ids if isinstance(dx_ids, str) else ";".join(dx_ids)
    pe = _normalize_pe(pe)
    cache_key = make_key(dx_key, ";".join(ou_list), pe, namespace="chak_coc_cells")
    hit = cache_get(cache_key)
    if hit is not None:
        return hit

    auth = HTTPBasicAuth(CHAK_USER, CHAK_PASS)
    out: dict[str, dict[str, float]] = {}
    for i in range(0, len(ou_list), ou_chunk):
        params = {
            "dimension": [f"dx:{dx_key}", "co:categoryOptions", f"pe:{pe}",
                          "ou:" + ";".join(ou_list[i:i + ou_chunk])],
            "paging": "false",
        }
        try:
            resp = chak_get("/analytics.json", params,
                            read_timeout=_CHAK_COC_READ_TIMEOUT, auth=auth)
        except Exception as exc:  # noqa: BLE001
            print(f"[DHIS2] CHAK COC cells fetch failed: {exc}")
            return {}
        if not resp.ok:
            print(f"[DHIS2] CHAK COC cells fetch HTTP {resp.status_code}")
            return {}
        data = resp.json()
        rows = data.get("rows", []) or []
        if not rows:
            continue
        meta = data.get("metaData", {}).get("items", {})
        hdrs = [h.get("name") for h in (data.get("headers") or [])]
        try:
            co_i, pe_i = hdrs.index("co"), hdrs.index("pe")
            val_i = hdrs.index("value")
        except ValueError:
            co_i, pe_i, val_i = 1, 2, len(rows[0]) - 1
        for row in rows:
            if len(row) <= max(co_i, pe_i, val_i):
                continue
            co_uid = str(row[co_i])
            # NOTE: `meta` is keyed by uid for *every* dimension, so a COC
            # uid would also resolve here — always take the period from the
            # pe column, never from the COC.
            pe_name = (meta.get(str(row[pe_i]), {}) or {}).get("name")
            if not pe_name:
                pe_name = str(row[pe_i])
            try:
                val = float(row[val_i] or 0)
            except (TypeError, ValueError):
                continue
            bucket = out.setdefault(pe_name, {})
            bucket[co_uid] = bucket.get(co_uid, 0.0) + val
    cache_set(cache_key, out)
    return out


def _chak_coc_name_totals(dx_ids, ou_ids, pe="LAST_12_MONTHS",
                          include=("preg", "breast"), ou_chunk=100):
    """Sum data element(s) restricted to the PrEP *typology* COCs.

    The PBIX computes `PrEP New(PBFW)` and `PrEP Initiated ANC` by
    filtering the `PrEP New Total` element with

        'PrEP Typologies'[PrEP Typologies] IN {"Pregnant","Breastfeeding"}

    DHIS2 carries the same typology as the *third* token of the category
    option combo name (e.g. "20-24 years, Female, Breastfeeding"), so a
    case-insensitive substring match on the COC name reproduces that DAX
    exactly — no extra dimension request and no hard-coded COC uid list.

    `include` is the tuple of typology tokens to keep, lower-cased.

    Returns {period_name: value} — {} on any failure.  (Shaped like
    ``_dhis2_fetch`` so it can be dropped into the same metric loop.)
    """
    from services.analytics_cache import get as cache_get, make_key, store as cache_set

    from requests.auth import HTTPBasicAuth

    if isinstance(ou_ids, (list, set, tuple)):
        ou_list = [str(o) for o in ou_ids if o]
    else:
        ou_list = [str(ou_ids)] if ou_ids else []
    if not ou_list:
        return {}

    dx_key = dx_ids if isinstance(dx_ids, str) else ";".join(dx_ids)
    tokens = tuple(str(t).lower() for t in include)
    if not tokens:
        return {}
    pe = _normalize_pe(pe)
    cache_key = make_key(dx_key, ";".join(ou_list), pe, ",".join(tokens),
                         namespace="chak_coc_name_totals")
    hit = cache_get(cache_key)
    if hit is not None:
        return hit

    auth = HTTPBasicAuth(CHAK_USER, CHAK_PASS)
    out: dict[str, float] = {}
    for i in range(0, len(ou_list), ou_chunk):
        params = {
            "dimension": [f"dx:{dx_key}", "co:categoryOptions", f"pe:{pe}",
                          "ou:" + ";".join(ou_list[i:i + ou_chunk])],
            "paging": "false",
        }
        try:
            resp = chak_get("/analytics.json", params,
                            read_timeout=_CHAK_COC_READ_TIMEOUT, auth=auth)
        except Exception as exc:  # noqa: BLE001
            print(f"[DHIS2] CHAK typology fetch failed: {exc}")
            return {}
        if not resp.ok:
            print(f"[DHIS2] CHAK typology fetch HTTP {resp.status_code}")
            return {}
        data = resp.json()
        rows = data.get("rows", []) or []
        if not rows:
            continue
        meta = data.get("metaData", {}).get("items", {})
        hdrs = [h.get("name") for h in (data.get("headers") or [])]
        try:
            co_i, pe_i = hdrs.index("co"), hdrs.index("pe")
            val_i = hdrs.index("value")
        except ValueError:
            co_i, pe_i, val_i = 1, 2, len(rows[0]) - 1
        for row in rows:
            if len(row) <= max(co_i, pe_i, val_i):
                continue
            co_name = (meta.get(str(row[co_i]), {}) or {}).get("name", "")
            low = str(co_name).lower()
            if not any(t in low for t in tokens):
                continue
            pe_name = (meta.get(str(row[pe_i]), {}) or {}).get("name")
            if not pe_name:
                pe_name = str(row[pe_i])
            try:
                val = float(row[val_i] or 0)
            except (TypeError, ValueError):
                continue
            out[pe_name] = out.get(pe_name, 0.0) + val
    cache_set(cache_key, out)
    return out


def _find_dx_by_pattern(prefix_pattern, age_bands):
    """Find male & female DX IDs from the data element dictionary.
    prefix_pattern: e.g. 'Tx_New STA' or 'TX_Curr STA'
    age_bands: list of strings like ['<1','1-4',...]
    Returns (males_list, females_list) of 11-char UIDs each.
    """
    try:
        df_elements, _ = _superpower_load_dict()
    except Exception:
        return [], []
    names = df_elements["name"].astype(str)
    males, females = [], []
    for age in age_bands:
        # Handle both "Tx_New STA <1M" (no comma) and "TX_Curr STA <1,M" (comma)
        pat_m = rf"{prefix_pattern}\s+{age},?\s*M\b"
        pat_f = rf"{prefix_pattern}\s+{age},?\s*F\b"
        m_match = df_elements[names.str.match(pat_m, case=False, na=False)]
        f_match = df_elements[names.str.match(pat_f, case=False, na=False)]
        if not m_match.empty:
            males.append(m_match.iloc[0]["id"])
        if not f_match.empty:
            females.append(f_match.iloc[0]["id"])
    return males, females


